import React, { useState, useRef } from 'react';
import axios from 'axios';

/**
 * 阿里云服务连接测试按钮组件
 */
const AliyunTestButton: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [microphoneTesting, setMicrophoneTesting] = useState(false);
  const [recognitionTesting, setRecognitionTesting] = useState(false);
  const [synthesisTesting, setSynthesisTesting] = useState(false);
  const [result, setResult] = useState<{
    success: boolean;
    message: string;
  } | null>(null);
  
  // 存储音频相关的引用
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  /**
   * 测试阿里云语音服务连接
   */
  const testConnection = async () => {
    setLoading(true);
    setResult(null);
    
    try {
      console.log('开始发送请求到: /api/voice-config');
      // 调用获取Token的API
      const response = await axios.get('/api/voice-config', {
        // 添加额外时间确保请求不会过早超时
        timeout: 10000,
        // 添加跟踪参数
        params: {
          _t: new Date().getTime()
        }
      });
      
      console.log('收到响应:', response);
      
      if (response.data && response.data.token) {
        setResult({
          success: true,
          message: `连接成功! 已获取有效Token。AppKey: ${response.data.appKey.substring(0, 4)}...`
        });
      } else {
        console.error('响应格式不正确:', response.data);
        setResult({
          success: false,
          message: '获取Token失败，请检查服务器配置'
        });
      }
    } catch (error) {
      console.error('请求失败详情:', error);
      let errorMessage = error instanceof Error ? error.message : '未知错误';
      
      // 根据错误类型提供更具体的错误信息
      if (axios.isAxiosError(error)) {
        if (error.code === 'ECONNREFUSED') {
          errorMessage = '无法连接到后端服务器，请确保服务器正在运行';
        } else if (error.response) {
          errorMessage = `服务器返回错误: ${error.response.status} - ${JSON.stringify(error.response.data)}`;
        } else if (error.request) {
          errorMessage = '未收到响应，请检查网络连接和服务器状态';
        }
      }
      
      setResult({
        success: false,
        message: `连接失败: ${errorMessage}`
      });
    } finally {
      setLoading(false);
    }
  };

  /**
   * 测试麦克风
   */
  const testMicrophone = async () => {
    setMicrophoneTesting(true);
    setResult(null);
    
    try {
      // 请求麦克风权限
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      setResult({
        success: true,
        message: '麦克风测试成功，已获取录音权限'
      });

      // 3秒后停止麦克风
      setTimeout(() => {
        if (streamRef.current) {
          streamRef.current.getTracks().forEach(track => track.stop());
          streamRef.current = null;
        }
        setMicrophoneTesting(false);
      }, 3000);
    } catch (error) {
      setResult({
        success: false,
        message: `麦克风测试失败: ${error instanceof Error ? error.message : '未知错误'}`
      });
      setMicrophoneTesting(false);
    }
  };

  /**
   * 测试语音识别
   */
  const testRecognition = async () => {
    setRecognitionTesting(true);
    setResult(null);
    audioChunksRef.current = [];
    
    try {
      // 请求麦克风权限
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      
      // 创建 MediaRecorder 实例
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      
      // 设置数据可用时的回调
      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };
      
      // 录音停止时的回调
      mediaRecorder.onstop = async () => {
        setResult({
          success: true,
          message: '录音完成，正在识别...'
        });
        
        if (audioChunksRef.current.length > 0) {
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
          
          // 创建FormData对象上传音频文件
          const formData = new FormData();
          formData.append('audio', audioBlob, 'recording.wav');
          
          try {
            // 调用语音识别API
            const response = await axios.post('/api/speech-to-text', formData, {
              headers: {
                'Content-Type': 'multipart/form-data'
              }
            });
            
            if (response.data && response.data.result) {
              setResult({
                success: true,
                message: `识别成功! 识别结果: "${response.data.result}"`
              });
            } else {
              setResult({
                success: false,
                message: '识别失败，未获得识别结果'
              });
            }
          } catch (error) {
            setResult({
              success: false,
              message: `识别请求失败: ${error instanceof Error ? error.message : '未知错误'}`
            });
          }
        }
        
        setRecognitionTesting(false);
      };
      
      // 开始录音
      mediaRecorder.start(100);
      
      // 3秒后停止录音
      setTimeout(() => {
        if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
        }
      }, 3000);
      
    } catch (error) {
      setResult({
        success: false,
        message: `语音识别测试失败: ${error instanceof Error ? error.message : '未知错误'}`
      });
      setRecognitionTesting(false);
    }
  };

  /**
   * 测试语音合成
   */
  const testSynthesis = async () => {
    setSynthesisTesting(true);
    setResult(null);
    
    try {
      // 创建一段测试文本
      const testText = '这是一段测试文本，用于测试阿里云语音合成功能是否正常工作。';
      
      setResult({
        success: true,
        message: '正在请求阿里云语音合成...'
      });
      
      // 调用阿里云语音合成API
      const response = await axios.post('/api/text-to-speech', 
        { text: testText },
        { responseType: 'blob' } // 指定响应类型为blob
      );
      
      // 创建音频URL并播放
      const audioBlob = new Blob([response.data], { type: 'audio/mpeg' });
      const audioUrl = URL.createObjectURL(audioBlob);
      
      // 创建音频元素
      const audio = new Audio(audioUrl);
      audioRef.current = audio;
      
      // 设置音频播放完成事件
      audio.onended = () => {
        setResult({
          success: true,
          message: '语音合成测试成功，已完成播放'
        });
        setSynthesisTesting(false);
        
        // 释放URL
        URL.revokeObjectURL(audioUrl);
      };
      
      // 设置错误处理
      audio.onerror = () => {
        setResult({
          success: false,
          message: `语音播放失败`
        });
        setSynthesisTesting(false);
        
        // 释放URL
        URL.revokeObjectURL(audioUrl);
      };
      
      // 开始播放
      audio.play();
      
    } catch (error) {
      setResult({
        success: false,
        message: `语音合成测试失败: ${error instanceof Error ? error.message : '未知错误'}`
      });
      setSynthesisTesting(false);
    }
  };

  const buttonStyle = (disabled: boolean): React.CSSProperties => ({
    padding: '8px 16px',
    borderRadius: '4px',
    border: 'none',
    backgroundColor: disabled ? '#cccccc' : '#1976d2',
    color: 'white',
    cursor: disabled ? 'not-allowed' : 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '14px',
    fontWeight: 500,
    margin: '5px 0',
    transition: 'all 0.3s ease'
  });

  const resultStyle: React.CSSProperties = result?.success 
    ? { marginTop: '10px', color: '#4caf50', fontSize: '14px' }
    : { marginTop: '10px', color: '#f44336', fontSize: '14px' };

  return (
    <div style={{ margin: '10px 0', padding: '15px', backgroundColor: '#f0f0f0', borderRadius: '8px' }}>
      <h3 style={{ marginTop: 0, marginBottom: '10px', fontSize: '16px' }}>阿里云语音交互测试</h3>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <button 
          onClick={testConnection} 
          disabled={loading || microphoneTesting || recognitionTesting || synthesisTesting}
          style={buttonStyle(loading || microphoneTesting || recognitionTesting || synthesisTesting)}
        >
          {loading ? '测试中...' : '1. 测试阿里云连接'}
        </button>
        
        <button 
          onClick={testMicrophone} 
          disabled={loading || microphoneTesting || recognitionTesting || synthesisTesting}
          style={buttonStyle(loading || microphoneTesting || recognitionTesting || synthesisTesting)}
        >
          {microphoneTesting ? '正在测试麦克风...' : '2. 测试麦克风'}
        </button>
        
        <button 
          onClick={testRecognition} 
          disabled={loading || microphoneTesting || recognitionTesting || synthesisTesting}
          style={buttonStyle(loading || microphoneTesting || recognitionTesting || synthesisTesting)}
        >
          {recognitionTesting ? '正在录音中...' : '3. 测试语音识别'}
        </button>
        
        <button 
          onClick={testSynthesis} 
          disabled={loading || microphoneTesting || recognitionTesting || synthesisTesting}
          style={buttonStyle(loading || microphoneTesting || recognitionTesting || synthesisTesting)}
        >
          {synthesisTesting ? '正在播放语音...' : '4. 测试阿里云语音合成'}
        </button>
      </div>
      
      {result && (
        <div style={resultStyle}>
          <div style={{ fontWeight: 'bold', marginTop: '10px' }}>
            {result.success ? '✓ ' : '✗ '}
            {result.success ? '测试成功' : '测试失败'}
          </div>
          <div style={{ marginTop: '5px' }}>{result.message}</div>
        </div>
      )}
    </div>
  );
};

export default AliyunTestButton; 