import React, { useState, useEffect } from 'react';

// 卡通风格AI头像组件
const AiAvatar: React.FC = () => {
  const [imageError, setImageError] = useState(false);

  // 处理图片加载错误
  const handleImageError = () => {
    console.error('头像图片加载失败');
    setImageError(true);
  };

  // 图片路径
  const imagePath = process.env.PUBLIC_URL + '/images/pic.jpg';
  
  // 备用头像样式
  const fallbackAvatarStyle = {
    width: '100%',
    height: '100%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#4A90E2',
    color: 'white',
    fontSize: '2rem',
    fontWeight: 'bold'
  };

  return (
    <div className="assistant-avatar" title="AI科学助手" style={{
      width: '100px',
      height: '100px',
      borderRadius: '50%',
      overflow: 'hidden',
      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)'
    }}>
      {!imageError ? (
        <img 
          src={imagePath}
          alt="AI助手头像" 
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover'
          }}
          onError={handleImageError}
        />
      ) : (
        <div style={fallbackAvatarStyle}>AI</div>
      )}
    </div>
  );
};

export default AiAvatar; 