import { useState, useCallback } from 'react';
import { aiServiceFactory, ApiMode } from '../services/aiServiceFactory';
import { ChatCompletionMessageParam } from 'openai/resources/chat/completions';
import { AI_PROMPTS } from '../config/prompts';

// 定义消息类型，兼容ChatCompletionMessageParam
export type Message = {
  role: 'system' | 'user' | 'assistant' | 'function' | 'tool' | 'developer';
  content: string | null | { type: string; text: string; }[] | { tool_call_id: string; content: string };
  name?: string;
  tool_call_id?: string;
  tool_calls?: any[];
};

// 语音合成配置
interface SpeechSynthesisConfig {
  enabled: boolean;
  voice?: SpeechSynthesisVoice | null;
  rate?: number;
  pitch?: number;
  volume?: number;
}

// AI调用钩子的参数
interface UseAIOptions {
  speechSynthesis?: SpeechSynthesisConfig;
}

/**
 * AI调用钩子，提供与AI交互的能力
 */
export const useAI = (options: UseAIOptions = {}) => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reasoningContent, setReasoningContent] = useState<string>('');
  const [apiMode, setApiMode] = useState<ApiMode>(aiServiceFactory.getMode());

  // 默认语音合成配置
  const defaultSpeechConfig: SpeechSynthesisConfig = {
    enabled: false,
    rate: 1,
    pitch: 1,
    volume: 1,
  };

  // 合并语音合成配置
  const speechConfig = {
    ...defaultSpeechConfig,
    ...options.speechSynthesis,
  };

  // 切换API模式
  const switchApiMode = useCallback((mode: ApiMode) => {
    aiServiceFactory.setMode(mode);
    setApiMode(mode);
  }, []);

  /**
   * 生成AI响应
   * @param messages 消息列表
   * @param onProgress 实时响应回调
   * @param onReasoningProgress 推理过程回调
   * @returns 返回AI的完整响应
   */
  const generateResponse = async (
    messages: ChatCompletionMessageParam[] | Message[],
    onProgress?: (content: string) => void,
    onReasoningProgress?: (reasoning: string) => void
  ) => {
    setIsLoading(true);
    setError(null);
    let fullResponse = "";

    try {
      // 实际项目中应连接后端API
      // 首先检查是否使用了真实API模式
      if (apiMode === 'real') {
        // 获取当前模式下的服务
        const service = aiServiceFactory.getService();
        
        // 调用服务生成响应
        const response = await service.generateResponse(
          messages as ChatCompletionMessageParam[], 
          onProgress,
          onReasoningProgress
        );
        return response;
      } else {
        // 模拟模式下使用固定回复
        const answer = "这是AI助手的回复。我能帮助你解答问题、提供信息或完成各种任务。如果你有任何问题，请随时告诉我。";
        
        // 模拟流式响应
        const words = answer.split('');
        
        for (let i = 0; i < words.length; i++) {
          const char = words[i];
          await new Promise(resolve => setTimeout(resolve, 20)); // 模拟延迟
          fullResponse += char;
          onProgress?.(char);
        }
        
        // 如果启用了语音合成，朗读AI的回复
        if (speechConfig.enabled && "speechSynthesis" in window) {
          speakText(fullResponse);
        }

        return fullResponse;
      }
    } catch (err) {
      console.error('AI响应生成错误:', err);
      const errorMessage = err instanceof Error ? err.message : '未知错误';
      setError(errorMessage);
      return null;
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * 语音合成，朗读文本
   * @param text 要朗读的文本
   */
  const speakText = (text: string) => {
    if (!("speechSynthesis" in window)) {
      console.error("浏览器不支持语音合成API");
      return;
    }

    // 停止现有的朗读
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    
    // 设置语音合成参数
    if (speechConfig.voice) {
      utterance.voice = speechConfig.voice;
    }
    
    utterance.rate = speechConfig.rate || 1;
    utterance.pitch = speechConfig.pitch || 1;
    utterance.volume = speechConfig.volume || 1;
    
    // 自动检测语言
    if (!utterance.voice) {
      // 尝试查找中文语音
      const voices = window.speechSynthesis.getVoices();
      const chineseVoice = voices.find(voice => 
        voice.lang.includes('zh') || voice.lang.includes('cmn')
      );
      
      if (chineseVoice) {
        utterance.voice = chineseVoice;
      }
    }
    
    // 开始朗读
    window.speechSynthesis.speak(utterance);
  };

  /**
   * 切换语音合成功能
   * @param enabled 是否启用语音合成
   */
  const toggleSpeechSynthesis = (enabled: boolean) => {
    speechConfig.enabled = enabled;
  };

  /**
   * 停止语音朗读
   */
  const stopSpeaking = () => {
    if ("speechSynthesis" in window) {
      window.speechSynthesis.cancel();
    }
  };

  /**
   * 设置语音合成的声音
   * @param voice 语音
   */
  const setVoice = (voice: SpeechSynthesisVoice) => {
    speechConfig.voice = voice;
  };

  /**
   * 获取可用的语音列表
   */
  const getAvailableVoices = (): SpeechSynthesisVoice[] => {
    if (!("speechSynthesis" in window)) return [];
    return window.speechSynthesis.getVoices();
  };

  // 测试API连接
  const testConnection = useCallback(async () => {
    try {
      const service = aiServiceFactory.getService();
      return await service.testConnection();
    } catch (error: any) {
      return { 
        success: false, 
        message: error?.message || '连接测试失败' 
      };
    }
  }, []);

  return {
    isLoading,
    error,
    reasoningContent,
    apiMode,
    switchApiMode,
    generateResponse,
    testConnection,
    // 语音合成相关功能
    speakText,
    toggleSpeechSynthesis,
    stopSpeaking,
    setVoice,
    getAvailableVoices,
    isSpeechEnabled: speechConfig.enabled
  };
};

export default useAI; 