import React, { useState, useRef, useEffect } from 'react';
import { useAI, Message } from '../hooks/useAI';
import LoadingSpinner from './LoadingSpinner';
import { AI_PROMPTS } from '../config/prompts';
import VoiceButton from './VoiceButton';
import VoiceToggleButton from './VoiceToggleButton';
import AliyunTestButton from './AliyunTestButton';
import AiAvatar from './AiAvatar';
import '../styles/ChatPage.css';
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { Components } from 'react-markdown/lib/ast-to-react';

// 消息类型定义，包含ID和时间戳
interface ChatMessage extends Message {
  id: string;
  timestamp: number;
}

// 消息分组处理函数
const groupMessagesByDate = (messages: ChatMessage[]) => {
  const groups: { [key: string]: ChatMessage[] } = {};
  
  messages.forEach(message => {
    const date = new Date(message.timestamp);
    const dateKey = date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
    
    if (!groups[dateKey]) {
      groups[dateKey] = [];
    }
    
    groups[dateKey].push(message);
  });
  
  return groups;
};

// 格式化时间
const formatTime = (timestamp: number) => {
  return new Date(timestamp).toLocaleTimeString('zh-CN', {
    hour: '2-digit',
    minute: '2-digit'
  });
};

// 本地存储键
const STORAGE_KEY = 'ai-mind-map-chat-history';

const ChatPage: React.FC = () => {
  const [speechEnabled, setSpeechEnabled] = useState(false);
  const [showTestButton, setShowTestButton] = useState(false);
  const { 
    generateResponse, 
    isLoading, 
    error, 
    toggleSpeechSynthesis, 
    isSpeechEnabled 
  } = useAI({
    speechSynthesis: {
      enabled: speechEnabled,
      rate: 1,
      pitch: 1,
      volume: 1
    }
  });
  
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Array<ChatMessage>>(() => {
    // 从本地存储加载聊天历史
    const savedMessages = localStorage.getItem(STORAGE_KEY);
    if (savedMessages) {
      try {
        return JSON.parse(savedMessages);
      } catch (e) {
        console.error('加载聊天历史失败', e);
        return [];
      }
    }
    return [];
  });
  const [streamingResponse, setStreamingResponse] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [isComposing, setIsComposing] = useState(false); // 处理输入法状态

  // 滚动到最新消息
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, streamingResponse]);

  // 保存消息到本地存储
  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    }
  }, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;
    
    // 创建带有ID和时间戳的消息
    const userMessage: ChatMessage = {
      role: 'user',
      content: input,
      id: `user-${Date.now()}`,
      timestamp: Date.now()
    };
    
    // 添加用户消息到对话列表
    setMessages(prev => [...prev, userMessage]);
    
    // 清空输入框和流式响应
    const userInput = input;
    setInput('');
    setStreamingResponse('');

    const apiMessages: Message[] = [
      { 
        role: 'system', 
        content: AI_PROMPTS.system
      },
      ...messages.map(msg => ({
        role: msg.role,
        content: msg.content
      })),
      { 
        role: 'user', 
        content: userInput 
      }
    ];

    // 处理流式响应
    const onProgress = (content: string) => {
      setStreamingResponse(prev => prev + content);
    };

    try {
      const result = await generateResponse(apiMessages, onProgress);
      if (result) {
        // 添加AI响应到对话列表
        const assistantMessage: ChatMessage = {
          role: 'assistant',
          content: result,
          id: `assistant-${Date.now()}`,
          timestamp: Date.now()
        };
        setMessages(prev => [...prev, assistantMessage]);
        setStreamingResponse('');
      }
    } catch (err) {
      console.error('生成响应失败:', err);
      setStreamingResponse('');
    }
  };

  // 处理语音识别结果
  const handleVoiceResult = (text: string) => {
    if (text.trim()) {
      setInput(text);
    }
  };

  // 处理语音合成开关变化
  const handleSpeechToggle = (enabled: boolean) => {
    setSpeechEnabled(enabled);
    toggleSpeechSynthesis(enabled);
  };

  // 切换阿里云测试按钮的显示状态
  const toggleTestButton = () => {
    setShowTestButton(prev => !prev);
  };

  // 自动调整文本区域的高度
  const handleTextareaInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const textarea = e.target;
    setInput(textarea.value);
    
    // 重置高度以获取正确的scrollHeight
    textarea.style.height = 'auto';
    // 设置新高度，但是最大高度限制为150px
    textarea.style.height = `${Math.min(textarea.scrollHeight, 150)}px`;
  };

  // 清空所有消息
  const clearMessages = () => {
    if (window.confirm('确定要清空所有对话记录吗？')) {
      setMessages([]);
      setStreamingResponse('');
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  // 基于日期分组消息
  const groupedMessages = groupMessagesByDate(messages);

  // 定义Markdown组件
  const markdownComponents: Components = {
    code({ node, inline, className, children, ...props }) {
      const match = /language-(\w+)/.exec(className || '');
      return !inline && match ? (
        <SyntaxHighlighter
          style={vscDarkPlus}
          language={match[1]}
          PreTag="div"
          {...props}
        >
          {String(children).replace(/\n$/, '')}
        </SyntaxHighlighter>
      ) : (
        <code className={className} {...props}>
          {children}
        </code>
      );
    }
  };

  // 渲染消息内容，支持Markdown和代码高亮
  const renderMessageContent = (content: string) => {
    return (
      <ReactMarkdown components={markdownComponents}>
        {content}
      </ReactMarkdown>
    );
  };

  // 导出聊天记录
  const exportChatHistory = () => {
    const chatData = JSON.stringify(messages, null, 2);
    const blob = new Blob([chatData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    a.href = url;
    a.download = `聊天记录-${timestamp}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // 导入聊天记录
  const importChatHistory = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target?.result as string;
        const importedMessages = JSON.parse(content);
        if (Array.isArray(importedMessages)) {
          setMessages(importedMessages);
          localStorage.setItem(STORAGE_KEY, content);
        } else {
          alert('文件格式不正确');
        }
      } catch (err) {
        console.error('导入聊天记录失败:', err);
        alert('导入失败，请检查文件格式');
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // 重置文件输入
  };

  return (
    <div className="chat-page">
      {/* 左侧消息区域 */}
      <div className="messages-container">
        {/* 消息控制栏 */}
        <div className="messages-header">
          <h2 className="chat-title">
            <span className="chat-title-icon">🧪</span> 
            AI科学助手
          </h2>
          <div className="messages-actions">
            <input
              type="file"
              id="import-chat"
              className="import-input"
              accept=".json"
              onChange={importChatHistory}
            />
            <label htmlFor="import-chat" className="import-button" title="导入聊天记录">
              📥 导入
            </label>
            <button 
              onClick={exportChatHistory}
              className="export-button"
              title="导出聊天记录"
            >
              📤 导出
            </button>
            <button 
              onClick={clearMessages}
              className="clear-button"
              title="清空对话"
            >
              🗑️ 清空
            </button>
            <button 
              onClick={toggleTestButton}
              className="test-button-toggle"
            >
              {showTestButton ? '隐藏测试' : '显示测试'}
            </button>
            <VoiceToggleButton 
              isEnabled={speechEnabled} 
              onChange={handleSpeechToggle}
              className="voice-toggle"
            />
          </div>
        </div>

        {/* 阿里云测试按钮 */}
        {showTestButton && <AliyunTestButton />}
        
        {/* 消息列表 */}
        <div className="messages-list">
          {messages.length === 0 && !streamingResponse && (
            <div className="message assistant-message welcome-message-container">
              <AiAvatar />
              <div className="welcome-message">
                <h3>欢迎使用AI科学助手</h3>
                <p>我是你的化学顾问，可以解答各种化学问题、解释复杂概念，或者讨论实验方案设计。</p>
                <div className="suggestion-chips">
                  <button 
                    className="suggestion-chip"
                    onClick={() => setInput("解释一下化学反应这个概念")}
                  >
                    解释一下化学反应这个概念
                  </button>
                  <button 
                    className="suggestion-chip"
                    onClick={() => setInput("化学反应的原理")}
                  >
                    化学反应的原理
                  </button>
                  <button 
                    className="suggestion-chip"
                    onClick={() => setInput("化学常用的除酸剂有哪些")}
                  >
                    化学常用的除酸剂有哪些
                  </button>
                </div>
              </div>
            </div>
          )}
          
          {/* 分组显示消息 */}
          {Object.entries(groupedMessages).map(([date, dateMessages]) => (
            <div key={date} className="message-group">
              <div className="date-divider">
                <span>{date}</span>
              </div>
              
              {dateMessages.map((msg) => (
                <div 
                  key={msg.id}
                  className={`message ${msg.role === 'user' ? 'user-message' : 'assistant-message'}`}
                >
                  {msg.role === 'assistant' && <AiAvatar />}
                  <div className="message-content">
                    <div className="message-bubble">
                      {typeof msg.content === 'string' ? renderMessageContent(msg.content) : ''}
                    </div>
                    <div className="message-time">{formatTime(msg.timestamp)}</div>
                  </div>
                </div>
              ))}
            </div>
          ))}

          {/* 显示正在生成的响应 */}
          {streamingResponse && (
            <div className="message assistant-message">
              <AiAvatar />
              <div className="message-content">
                <div className="message-bubble">
                  {renderMessageContent(streamingResponse)}
                  <span className="typing-indicator"></span>
                </div>
                <div className="message-time">{formatTime(Date.now())}</div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* 底部输入区域 */}
      <div className="input-container">
        <form onSubmit={handleSubmit} className="input-form">
          <div className="textarea-wrapper">
            <textarea
              value={input}
              onChange={handleTextareaInput}
              placeholder="输入你的消息..."
              className="message-input"
              rows={1}
              onCompositionStart={() => setIsComposing(true)}
              onCompositionEnd={() => setIsComposing(false)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey && !isComposing) {
                  e.preventDefault();
                  if (input.trim()) handleSubmit(e);
                }
              }}
            />
            <VoiceButton 
              onResult={handleVoiceResult} 
              className="voice-button"
            />
          </div>
          
          <button 
            type="submit" 
            disabled={isLoading || !input.trim()}
            className={`send-button ${isLoading || !input.trim() ? 'disabled' : ''}`}
          >
            {isLoading ? <LoadingSpinner /> : '发送'}
          </button>
        </form>

        {error && (
          <div className="error-message">
            错误: {error}
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage; 