import { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';

// 阿里云语音识别状态枚举
export enum VoiceRecognitionStatus {
  IDLE = 'idle',          // 空闲状态
  CONNECTING = 'connecting', // 连接中
  RECORDING = 'recording',   // 录音中
  RECOGNIZING = 'recognizing', // 识别中
  ERROR = 'error'         // 错误状态
}

// 语音交互钩子参数接口
interface UseVoiceInteractionProps {
  onResult?: (text: string) => void;
  onError?: (error: Error) => void;
  onStatusChange?: (status: VoiceRecognitionStatus) => void;
  autoStart?: boolean;
}

/**
 * 语音交互钩子函数，用于集成阿里云智能语音交互
 */
export const useVoiceInteraction = ({
  onResult,
  onError,
  onStatusChange,
  autoStart = false
}: UseVoiceInteractionProps = {}) => {
  const [status, setStatus] = useState<VoiceRecognitionStatus>(VoiceRecognitionStatus.IDLE);
  const [isListening, setIsListening] = useState(false);
  const [text, setText] = useState('');
  const [error, setError] = useState<Error | null>(null);
  
  // 用于存储音频相关资源的引用
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);
  
  // 阿里云语音识别配置
  const [config, setConfig] = useState({
    appKey: '',
    token: '',
    url: ''
  });

  /**
   * 更新语音识别状态
   */
  const updateStatus = useCallback((newStatus: VoiceRecognitionStatus) => {
    setStatus(newStatus);
    onStatusChange?.(newStatus);
  }, [onStatusChange]);

  /**
   * 处理错误
   */
  const handleError = useCallback((err: Error) => {
    console.error('语音识别错误:', err);
    setError(err);
    updateStatus(VoiceRecognitionStatus.ERROR);
    onError?.(err);
    stopListening();
  }, [onError, updateStatus]);

  /**
   * 从服务端获取阿里云语音识别所需的配置
   */
  const fetchConfig = useCallback(async () => {
    try {
      // 实际项目中，应该从自己的服务端获取token等配置
      // 服务端负责从阿里云获取token，并返回给前端
      const response = await axios.get('/api/voice-config');
      const data = response.data;
      setConfig({
        appKey: data.appKey,
        token: data.token,
        url: data.url
      });
      return data;
    } catch (err) {
      handleError(err instanceof Error ? err : new Error('获取语音识别配置失败'));
      return null;
    }
  }, [handleError]);

  /**
   * 识别音频数据
   */
  const recognizeSpeech = useCallback(async (audioBlob: Blob) => {
    try {
      updateStatus(VoiceRecognitionStatus.RECOGNIZING);
      
      // 创建FormData对象上传音频文件
      const formData = new FormData();
      formData.append('audio', audioBlob, 'recording.wav');
      
      // 调用服务端API进行语音识别
      const response = await axios.post('/api/speech-to-text', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'Authorization': `Bearer ${config.token}`
        }
      });
      
      // 获取识别结果
      const data = response.data;
      if (data && data.result) {
        setText(data.result);
        onResult?.(data.result);
      }
      
      updateStatus(VoiceRecognitionStatus.IDLE);
    } catch (err) {
      handleError(err instanceof Error ? err : new Error('语音识别失败'));
    }
  }, [config.token, handleError, onResult, updateStatus]);

  /**
   * 获取麦克风权限并开始录音
   */
  const startListening = useCallback(async () => {
    if (isListening) return;
    
    try {
      updateStatus(VoiceRecognitionStatus.CONNECTING);
      
      // 获取配置
      const configData = await fetchConfig();
      if (!configData) return;
      
      // 清理之前的状态
      setText('');
      setError(null);
      audioChunksRef.current = [];
      
      // 请求麦克风权限
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      
      // 创建 MediaRecorder 实例
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      
      // 设置数据可用时的回调
      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };
      
      // 录音停止时的回调
      mediaRecorder.onstop = async () => {
        if (audioChunksRef.current.length > 0) {
          // 合并音频数据
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
          
          // 发送到服务器进行识别
          await recognizeSpeech(audioBlob);
        }
      };
      
      // 开始录音
      mediaRecorder.start(100); // 每100ms触发一次ondataavailable事件
      setIsListening(true);
      updateStatus(VoiceRecognitionStatus.RECORDING);
      
    } catch (err) {
      handleError(err instanceof Error ? err : new Error('获取麦克风权限失败'));
    }
  }, [fetchConfig, handleError, isListening, recognizeSpeech, updateStatus]);

  /**
   * 停止录音并开始识别
   */
  const stopListening = useCallback(() => {
    if (!isListening) return;
    
    try {
      // 停止MediaRecorder
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
      }
      
      // 停止所有音轨
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      
      setIsListening(false);
    } catch (err) {
      handleError(err instanceof Error ? err : new Error('停止录音失败'));
    }
  }, [isListening, handleError]);

  // 初始化时获取配置，如果设置了自动开始则启动语音识别
  useEffect(() => {
    if (autoStart) {
      startListening();
    }
    
    // 组件卸载时清理资源
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [autoStart, startListening]);

  return {
    startListening,
    stopListening,
    isListening,
    text,
    status,
    error
  };
};

export default useVoiceInteraction; 