import React, { useState, useCallback } from 'react';
import { useVoiceInteraction, VoiceRecognitionStatus } from '../hooks/useVoiceInteraction';

interface VoiceButtonProps {
  onResult?: (text: string) => void;
  className?: string;
}

const VoiceButton: React.FC<VoiceButtonProps> = ({ onResult, className = '' }) => {
  const [isRecording, setIsRecording] = useState(false);

  // 使用语音交互钩子
  const { startListening, stopListening, isListening, status, error } = useVoiceInteraction({
    onResult: (text) => {
      if (onResult && text.trim()) {
        onResult(text);
      }
      setIsRecording(false);
    },
    onError: (err) => {
      console.error('语音识别错误:', err);
      setIsRecording(false);
    },
    onStatusChange: (newStatus) => {
      if (newStatus === VoiceRecognitionStatus.ERROR) {
        setIsRecording(false);
      }
    }
  });

  // 处理按钮点击
  const handleButtonClick = useCallback(() => {
    if (isRecording) {
      stopListening();
      setIsRecording(false);
    } else {
      startListening();
      setIsRecording(true);
    }
  }, [isRecording, startListening, stopListening]);

  // 获取按钮样式
  const getButtonStyle = useCallback(() => {
    const baseStyle: React.CSSProperties = {
      width: '40px',
      height: '40px',
      borderRadius: '50%',
      border: 'none',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      transition: 'all 0.2s ease',
      boxShadow: '0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.24)'
    };

    // 根据状态设置不同的样式
    if (status === VoiceRecognitionStatus.ERROR) {
      return {
        ...baseStyle,
        backgroundColor: '#f44336',
        transform: 'scale(1.0)'
      };
    } else if (isRecording) {
      return {
        ...baseStyle,
        backgroundColor: '#f44336',
        transform: 'scale(1.1)',
        boxShadow: '0 3px 6px rgba(0,0,0,0.16), 0 3px 6px rgba(0,0,0,0.23)',
        animation: status === VoiceRecognitionStatus.RECORDING ? 'pulse 1.5s infinite' : 'none'
      };
    } else {
      return {
        ...baseStyle,
        backgroundColor: '#2196f3'
      };
    }
  }, [isRecording, status]);

  // 定义脉冲动画的样式
  const pulseAnimationStyle: React.CSSProperties = {
    position: 'absolute',
    width: '100%',
    height: '100%',
    left: '0',
    top: '0'
  };

  return (
    <div style={{ position: 'relative' }}>
      <button
        className={`voice-button ${className}`}
        onClick={handleButtonClick}
        style={getButtonStyle()}
        title={isRecording ? '点击停止录音' : '点击开始语音输入'}
        disabled={status === VoiceRecognitionStatus.CONNECTING || status === VoiceRecognitionStatus.RECOGNIZING}
      >
        {isRecording ? (
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect x="6" y="6" width="12" height="12" rx="2" fill="white" />
          </svg>
        ) : (
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M12 15C13.66 15 15 13.66 15 12V6C15 4.34 13.66 3 12 3C10.34 3 9 4.34 9 6V12C9 13.66 10.34 15 12 15Z" fill="white" />
            <path d="M17 12C17 14.76 14.76 17 12 17C9.24 17 7 14.76 7 12H5C5 15.53 7.61 18.43 11 18.93V21H13V18.93C16.39 18.43 19 15.53 19 12H17Z" fill="white" />
          </svg>
        )}
      </button>

      {/* 添加全局样式 */}
      <style>
        {`
          @keyframes pulse {
            0% {
              transform: scale(1.1);
            }
            50% {
              transform: scale(1.2);
            }
            100% {
              transform: scale(1.1);
            }
          }
        `}
      </style>
    </div>
  );
};

export default VoiceButton;